/* ---------- drones ---------- */
const DRONE_COUNT = 9;
const FORMS = {
  DELTA(i, t, out){
    const row = i===0 ? 0 : Math.ceil(i/2);
    const side = i===0 ? 0 : (i%2===1 ? -1 : 1);
    return out.set(side*row*5.4, 8.5 + Math.sin(row*1.9)*1.3, -16 + row*6.8);
  },
  RING(i, t, out){
    const a = i/DRONE_COUNT*Math.PI*2 + t*0.12;
    return out.set(Math.cos(a)*15, 9.5 + Math.sin(i*2.3)*1.6, -6 + Math.sin(a)*15);
  },
  GRID(i, t, out){
    const ix = i%3, iz = (i/3)|0;
    return out.set(-14 + ix*14, 7 + ((ix+iz)%3)*2.4, -20 + iz*15);
  },
  PATROL(i, t, out){
    const lanes = [-12, -6, 0, 6, 12];
    return out.set(lanes[i%5], 8.5 + Math.sin(t*0.55 + i*1.3)*2.6, Math.sin(t*0.2 + i*1.3)*40);
  },
};
const hullMat  = new THREE.MeshStandardMaterial({ color:0x2b3138, metalness:0.85, roughness:0.35 });
const podMat   = new THREE.MeshStandardMaterial({ color:0x14171c, metalness:0.6, roughness:0.6 });
const coreMat  = new THREE.MeshStandardMaterial({ color:0x0a2a33, emissive:0x35d5ff, emissiveIntensity:2.2, roughness:0.4 });
const eyeMat   = new THREE.MeshStandardMaterial({ color:0x0a2a33, emissive:0x66e9ff, emissiveIntensity:3 });
const discMat  = new THREE.MeshBasicMaterial({ color:0x9fb9cc, transparent:true, opacity:0.13, depthWrite:false, side:THREE.DoubleSide });
const drones = [];
for(let i=0;i<DRONE_COUNT;i++){
  const g = new THREE.Group(); g.rotation.order = 'YXZ';
  const hull = mesh(new THREE.CylinderGeometry(0.95, 1.15, 0.5, 8), hullMat);
  hull.rotation.y = Math.PI/8; hull.castShadow = true; g.add(hull);
  const core = mesh(new THREE.TorusGeometry(0.98, 0.05, 8, 32), coreMat);
  core.rotation.x = Math.PI/2; core.position.y = -0.1; g.add(core);
  const eye = mesh(new THREE.SphereGeometry(0.17, 12, 10), eyeMat);
  eye.position.set(0, 0.08, -1.05); g.add(eye);
  const bellyMat = new THREE.MeshStandardMaterial({ color:0x0a1418, emissive:0x9fdcff, emissiveIntensity:1.4 });
  const belly = mesh(new THREE.CylinderGeometry(0.26, 0.3, 0.08, 10), bellyMat);
  belly.position.y = -0.33; g.add(belly);
  const ant = mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.6, 6), podMat);
  ant.position.set(0.35, 0.5, 0.35); g.add(ant);
  const tipMat = new THREE.MeshStandardMaterial({ color:0x220000, emissive:0xff3322, emissiveIntensity:0.6 });
  const tip = mesh(new THREE.SphereGeometry(0.05, 8, 6), tipMat);
  tip.position.set(0.35, 0.82, 0.35); g.add(tip);
  const blades = [], navs = [];
  for(const [sx, sz] of [[1,1],[1,-1],[-1,1],[-1,-1]]){
    const arm = mesh(new THREE.BoxGeometry(1.9, 0.12, 0.26), hullMat);
    arm.position.set(sx*0.55, 0.02, sz*0.55); arm.rotation.y = -sx*sz*Math.PI/4;
    arm.castShadow = true; g.add(arm);
    const pod = mesh(new THREE.CylinderGeometry(0.15, 0.19, 0.3, 10), podMat);
    pod.position.set(sx*1.25, 0.12, sz*1.25); g.add(pod);
    const ring = mesh(new THREE.TorusGeometry(0.55, 0.035, 8, 24), podMat);
    ring.rotation.x = Math.PI/2; ring.position.set(sx*1.25, 0.24, sz*1.25); g.add(ring);
    const bg = new THREE.Group(); bg.position.set(sx*1.25, 0.3, sz*1.25);
    bg.add(mesh(new THREE.BoxGeometry(1.15, 0.02, 0.1), podMat));
    bg.add(mesh(new THREE.BoxGeometry(0.1, 0.02, 1.15), podMat));
    const disc = mesh(new THREE.CircleGeometry(0.55, 20), discMat);
    disc.rotation.x = -Math.PI/2; disc.position.y = -0.005; bg.add(disc);
    g.add(bg); blades.push({ g:bg, dir: sx*sz > 0 ? 1 : -1 });
    const navMat = new THREE.MeshStandardMaterial({ color:0x111111,
      emissive: sx < 0 ? 0xff2b2b : 0x2bff66, emissiveIntensity:0.15 });
    const nav = mesh(new THREE.BoxGeometry(0.12, 0.12, 0.12), navMat);
    nav.position.set(sx*1.45, 0.1, sz*1.45); g.add(nav);
    navs.push(navMat);
  }
  g.scale.setScalar(1.7); scene.add(g);
  const d = { g, blades, navs, tipMat, bellyMat, phase:i*1.37, i,
    pos:new THREE.Vector3(), prev:new THREE.Vector3(), yaw:Math.PI, bank:0, pitch:0 };
  FORMS.DELTA(i, 0, d.pos); d.prev.copy(d.pos);
  if (i === 0){
    const lsp = new THREE.SpotLight(0xbfe4ff, 700, 45, 0.4, 0.6, 1.8);
    lsp.position.set(0, -0.3, 0);
    const lt = new THREE.Object3D(); lt.position.set(0, -25, 0);
    g.add(lsp, lt); lsp.target = lt;
  }
  drones.push(d);
}

