/* ---------- animation ---------- */
const clock = new THREE.Clock();
let t = 0, booted = false, frames = 0, fpsT = 0;
const vA = new THREE.Vector3(), vB = new THREE.Vector3();
const cTmp = new THREE.Color();
const bootEl = document.getElementById('boot');
const ease = x => x*x*(3-2*x);

function updateDrones(dt){
  for(const d of drones){
    FORMS[state.form](d.i, t, vA);
    const k = 1 - Math.exp(-dt*1.5);
    vB.copy(vA).sub(d.pos).multiplyScalar(k);
    d.pos.add(vB);
    const vel = vB.divideScalar(Math.max(dt, 1e-4));
    d.g.position.copy(d.pos);
    d.g.position.y += Math.sin(t*1.8 + d.phase)*0.28;
    if (vel.lengthSq() > 0.04){
      const yawT = Math.atan2(vel.x, vel.z);
      let dy = yawT - d.yaw;
      dy = Math.atan2(Math.sin(dy), Math.cos(dy));
      d.yaw += dy * (1 - Math.exp(-dt*2.5));
    }
    const cos = Math.cos(d.yaw), sin = Math.sin(d.yaw);
    const lat = vel.x*cos - vel.z*sin;
    const fwd = vel.x*sin + vel.z*cos;
    const bankT = THREE.MathUtils.clamp(-lat*0.045, -0.55, 0.55);
    const pitchT = THREE.MathUtils.clamp(fwd*0.02, -0.3, 0.3);
    d.bank += (bankT - d.bank)*(1 - Math.exp(-dt*3));
    d.pitch += (pitchT - d.pitch)*(1 - Math.exp(-dt*3));
    d.g.rotation.set(d.pitch, d.yaw, d.bank);
    for(const b of d.blades) b.g.rotation.y += b.dir*40*dt;
    const blink = (t*0.9 + d.phase) % 1 < 0.12;
    d.navs[0].emissiveIntensity = blink ? 4 : 0.12;
    d.navs[1].emissiveIntensity = ((t*0.9 + d.phase + 0.5) % 1 < 0.12) ? 4 : 0.12;
    d.tipMat.emissiveIntensity = ((t*0.45 + d.phase) % 1 < 0.08) ? 3 : 0.4;
    d.bellyMat.emissiveIntensity = 1.2 + 0.6*Math.sin(t*2.2 + d.phase);
  }
}

renderer.setAnimationLoop(()=>{
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt;
  const T = clock.elapsedTime;

  /* runway chase + scroll */
  for(let i=0;i<stripPos.length;i++){
    const s = Math.pow(0.5 + 0.5*Math.sin(t*2.4 - i*0.55), 4);
    const b = (0.12 + 0.88*s)*1.7;
    strips.setColorAt(i, cTmp.setRGB(0.44*b, 0.89*b, b));
  }
  strips.instanceColor.needsUpdate = true;
  runwayTex.offset.y -= dt*0.012;

  /* door chevrons */
  hazardTex.offset.x += dt*0.08;
  chevMat.emissiveIntensity = 1.4 + 0.7*Math.sin(t*3);

  /* beacons */
  for(const b of beacons){
    b.pivot.rotation.y += dt*2.6;
    const p = 0.5 + 0.5*Math.sin(t*4);
    b.bulbMat.emissiveIntensity = 1.5 + 3.5*p;
    b.light.intensity = 40 + 160*p;
  }
  /* wall strobes: double-flash pattern */
  for(const s of strobes){
    const f = (t*0.9 + s.ph) % 1;
    const on = f < 0.07 || (f > 0.14 && f < 0.21);
    s.m.emissiveIntensity = on ? 3.5 : 0.05;
    if (s.l) s.l.intensity = on ? 55 : 0;
  }
  /* pad lights */
  padA.forEach((m,k)=>{ m.emissiveIntensity = ((t*0.5 + k*0.25) % 1 < 0.55) ? 2 : 0.3; });
  padB.forEach((m,k)=>{ m.emissiveIntensity = ((t*0.5 + k*0.25 + 0.4) % 1 < 0.55) ? 2 : 0.3; });
  engineGlow.emissiveIntensity = 1.6 + 0.5*Math.sin(t*2.1);

  /* fog planes + shafts breathe */
  for(const f of fogPlanes){
    f.t.offset.x += dt*f.sx; f.t.offset.y += dt*f.sy;
    f.m.material.opacity = f.base*(1 + 0.15*Math.sin(t*0.3 + f.ph));
  }
  shaftMat.opacity = 0.075 + 0.02*Math.sin(t*0.7);

  /* dust drift */
  const dp = dustGeo.attributes.position.array;
  for(let i=0;i<DUST;i++){
    dp[i*3+1] += dustSp[i]*dt;
    dp[i*3] += Math.sin(t*0.4 + i)*0.02*dt;
    if (dp[i*3+1] > 23) dp[i*3+1] = 0.4;
  }
  dustGeo.attributes.position.needsUpdate = true;

  updateDrones(dt);

  /* camera */
  const u = (t/72) % 1;
  pathPos.getPointAt(u, pPos);
  pathLook.getPointAt(u, pLook);
  pPos.x += Math.sin(t*0.9)*0.22 + Math.sin(t*2.3 + 1.7)*0.05;
  pPos.y += Math.sin(t*1.3 + 0.6)*0.14;
  if (state.camMode === 'free'){
    controls.update();
    curLook.copy(controls.target);

