const beacons = [];
function beacon(x, y, z){
  const grp = new THREE.Group(); grp.position.set(x, y, z);
  const base = mesh(new THREE.CylinderGeometry(0.5, 0.7, 0.5, 12), frameMat);
  base.position.y = 0.25; grp.add(base);
  const bulbMat = new THREE.MeshStandardMaterial({ color:0x330000, emissive:0xff2211, emissiveIntensity:3 });
  const bulb = mesh(new THREE.SphereGeometry(0.42, 16, 12), bulbMat);
  bulb.position.y = 0.78; grp.add(bulb);
  const pivot = new THREE.Group(); pivot.position.y = 0.78; grp.add(pivot);
  const cone = mesh(new THREE.ConeGeometry(2.4, 6, 20, 1, true), new THREE.MeshBasicMaterial({
    color:0xff3322, transparent:true, opacity:0.15, blending:THREE.AdditiveBlending,
    depthWrite:false, side:THREE.DoubleSide, fog:false }));
  cone.rotation.z = -Math.PI/2; cone.position.x = 3; pivot.add(cone);
  const light = new THREE.PointLight(0xff3322, 120, 34, 1.8); light.position.y = 0.8; grp.add(light);
  scene.add(grp); beacons.push({ pivot, bulbMat, light });
}
