const strobes = [];
function strobe(x, y, z, withLight){
  const m = new THREE.MeshStandardMaterial({ color:0x1a1a1a, emissive:0xffa040, emissiveIntensity:0.05 });
  const b = mesh(new THREE.BoxGeometry(0.22, 0.5, 0.22), m);
  b.position.set(x, y, z); scene.add(b);
  let l = null;
  if (withLight){ l = new THREE.PointLight(0xffa040, 0, 18, 1.8); l.position.set(x*0.92, y, z); scene.add(l); }
  strobes.push({ m, l, ph: Math.random()*10 });
}
